import copy
import decimal
import json
import random
import tomllib
from decimal import Decimal
from pathlib import Path

_DATA = tomllib.loads((Path(__file__).parent / "data.toml").read_text())


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _tx(blocking=False):
    def deco(fn):
        def wrapper(self, *a, **k):
            snap = copy.deepcopy(self._s)
            try:
                r = fn(self, *a, **k)
            except BaseException:
                self._s = snap
                raise
            self._undo = snap
            self._blocked = blocking
            return r
        wrapper.__name__ = fn.__name__
        return wrapper
    return deco


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, *,
                 late_penalty_pct=None, restock_perishable_returns=None):
        self._wh = list(warehouses)
        self._cap = dict(capacities)
        self._mode = rounding_mode
        self._late_pct = late_penalty_pct          # undecided by owner (C18)
        self._restock_perish = restock_perishable_returns  # undecided (C23)
        self._undo = None
        self._blocked = False
        self._s = {
            "cash": int(opening_cash), "day": 0, "items": {}, "lots": {},
            "log": [], "rel": {}, "suspended": [], "orders": {}, "next_order": 1,
            "shipped_sku": {}, "returned_sku": {}, "armed": {},
            "shipped": [0], "held": [],
        }

    # ---------- helpers ----------
    def _round(self, d):
        return int(Decimal(d).quantize(Decimal(1), rounding=self._mode))

    def _sku(self, sku):
        if sku not in self._s["items"]:
            raise DepotError("UNKNOWN_SKU")

    def _w(self, wh):
        if wh not in self._wh:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _qty(q):
        if isinstance(q, bool) or not isinstance(q, int) or q <= 0:
            raise DepotError("INVALID_QTY")

    def _units(self, sku=None, wh=None):
        t = 0
        for (s, w), lots in self._s["lots"].items():
            if (sku is None or s == sku) and (wh is None or w == wh):
                t += sum(q for _, q in lots)
        return t

    def _emit(self, *n):
        self._s["log"].append(tuple(n))

    def _check_overdrawn(self, prev):
        if prev >= 0 and self._s["cash"] < 0:
            self._emit("OVERDRAWN")

    def _add_lot(self, sku, wh, day, qty):
        lots = self._s["lots"].setdefault((sku, wh), [])
        lots.append([day, qty])
        lots.sort(key=lambda l: l[0])
        if self._units(sku, wh) > self._s["items"][sku]["reorder_level"]:
            self._s["armed"][(sku, wh)] = True

    def _consume(self, sku, wh, qty):
        """FIFO; returns consumed [day, qty] lots."""
        lots = self._s["lots"].get((sku, wh), [])
        out = []
        need = qty
        while need > 0:
            d, q = lots[0]
            t = min(q, need)
            out.append([d, t])
            need -= t
            if t == q:
                lots.pop(0)
            else:
                lots[0][1] -= t
        return out

    def _charge(self, amount):
        if self._s["cash"] - amount < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._s["cash"] -= amount

    def _rcv(self, sku, qty, wh):
        self._sku(sku)
        self._w(wh)
        self._qty(qty)
        if self._s["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._units(wh=wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")
        self._charge(self._s["items"][sku]["unit_cost"] * qty)
        self._add_lot(sku, wh, self._s["day"], qty)

    # ---------- operations ----------
    @_tx()
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        if sku in self._s["items"]:
            raise DepotError("DUPLICATE_SKU")
        if not isinstance(unit_cost, int) or isinstance(unit_cost, bool) or unit_cost <= 0:
            raise DepotError("INVALID_UNIT_COST")
        if not isinstance(reorder_level, int) or reorder_level < 0:
            raise DepotError("INVALID_REORDER_LEVEL")
        if shelf_life_days is not None and (
                not isinstance(shelf_life_days, int) or shelf_life_days < 1):
            raise DepotError("INVALID_SHELF_LIFE")
        self._s["items"][sku] = {"unit_cost": unit_cost,
                                 "reorder_level": reorder_level,
                                 "shelf": shelf_life_days}

    @_tx()
    def receive(self, sku, qty, wh):
        self._rcv(sku, qty, wh)

    @_tx()
    def receive_bulk(self, receipts):
        for sku, qty, wh in receipts:
            self._rcv(sku, qty, wh)

    @_tx()
    def ship(self, sku, qty, wh, price):
        self._sku(sku)
        self._w(wh)
        self._qty(qty)
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise DepotError("INVALID_PRICE")
        if self._units(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        total = Decimal(price * qty)
        if qty >= _DATA["bulk_threshold"]:
            total = total * (100 - _DATA["bulk_discount_pct"]) / Decimal(100)
        revenue = self._round(total)
        self._consume(sku, wh, qty)
        self._s["cash"] += revenue
        self._s["shipped"][-1] += qty
        self._s["shipped_sku"][sku] = self._s["shipped_sku"].get(sku, 0) + qty
        left = self._units(sku, wh)
        if left <= self._s["items"][sku]["reorder_level"] and \
                self._s["armed"].get((sku, wh), True):
            self._s["armed"][(sku, wh)] = False
            self._emit("REORDER", sku, wh)
        return revenue

    def list_price(self, sku):
        self._sku(sku)
        cost = self._s["items"][sku]["unit_cost"]
        return self._round(Decimal(cost) * (1 + Decimal(str(_DATA["markup"]))))

    @_tx()
    def transfer(self, sku, qty, from_wh, to_wh):
        self._sku(sku)
        self._w(from_wh)
        self._w(to_wh)
        self._qty(qty)
        if from_wh == to_wh:
            raise DepotError("SAME_WAREHOUSE")
        if self._units(sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if self._units(wh=to_wh) + qty > self._cap[to_wh]:
            raise DepotError("CAPACITY")
        self._charge(_DATA["transfer_credit_cents_per_unit"] * qty)
        for d, q in self._consume(sku, from_wh, qty):
            self._add_lot(sku, to_wh, d, q)

    @_tx(blocking=True)
    def advance_day(self):
        s = self._s
        prev = s["cash"]
        s["cash"] -= _DATA["storage_cents_per_unit_day"] * self._units()
        for sku in sorted(s["items"]):
            shelf = s["items"][sku]["shelf"]
            if shelf is None:
                continue
            for wh in self._wh:
                lots = s["lots"].get((sku, wh))
                if not lots:
                    continue
                keep = [l for l in lots if s["day"] - l[0] <= shelf]
                gone = sum(q for d, q in lots if s["day"] - d > shelf)
                lots[:] = keep
                if gone:
                    self._emit("EXPIRY", sku, wh, gone)
        self._check_overdrawn(prev)
        s["held"].append(self._units())
        s["day"] += 1
        s["shipped"].append(0)

    def notifications(self):
        return list(self._s["log"])

    @_tx()
    def place_order(self, supplier, sku, qty, due_day, wh=None):
        self._sku(sku)
        self._qty(qty)
        if wh is None:
            wh = self._wh[0]
        self._w(wh)
        s = self._s
        s["rel"].setdefault(supplier, 3)
        if supplier in s["suspended"]:
            raise DepotError("SUPPLIER_SUSPENDED")
        oid = s["next_order"]
        s["next_order"] += 1
        s["orders"][oid] = {"supplier": supplier, "sku": sku, "qty": qty,
                            "due": due_day, "wh": wh, "done": False}
        return oid

    @_tx()
    def deliver(self, order_id, day):
        s = self._s
        o = s["orders"].get(order_id)
        if o is None:
            raise DepotError("UNKNOWN_ORDER")
        if o["done"]:
            raise DepotError("ORDER_ALREADY_DELIVERED")
        late = day > o["due"]
        cost = Decimal(s["items"][o["sku"]]["unit_cost"] * o["qty"])
        if late:
            if self._late_pct is None:
                raise DepotError("LATE_PENALTY_UNDECIDED")
            cost = cost * (100 - Decimal(str(self._late_pct))) / Decimal(100)
        cost = self._round(cost)
        if self._units(wh=o["wh"]) + o["qty"] > self._cap[o["wh"]]:
            raise DepotError("CAPACITY")
        prev = s["cash"]
        self._charge(cost)
        self._add_lot(o["sku"], o["wh"], s["day"], o["qty"])
        o["done"] = True
        sup = o["supplier"]
        r = max(0, min(5, s["rel"][sup] + (-1 if late else 1)))
        s["rel"][sup] = r
        if r <= 1 and sup not in s["suspended"]:
            s["suspended"].append(sup)
            self._emit("SUPPLIER_SUSPENDED", sup)
        self._check_overdrawn(prev)

    @_tx()
    def reinstate(self, supplier):
        s = self._s
        if supplier not in s["rel"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        s["rel"][supplier] = 2
        if supplier in s["suspended"]:
            s["suspended"].remove(supplier)

    def reliability(self, supplier):
        if supplier not in self._s["rel"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self._s["rel"][supplier]

    @_tx()
    def audit(self, counts):
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for sku, wh in counts:
            self._sku(sku)
            self._w(wh)
        for (sku, wh) in sorted(counts):
            led = self._units(sku, wh)
            if led != counts[(sku, wh)]:
                self._emit("AUDIT_MISMATCH", sku, wh, led, counts[(sku, wh)])

    @_tx()
    def return_goods(self, sku, qty, wh, price):
        self._sku(sku)
        self._w(wh)
        self._qty(qty)
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise DepotError("INVALID_PRICE")
        s = self._s
        if s["returned_sku"].get(sku, 0) + qty > s["shipped_sku"].get(sku, 0):
            raise DepotError("RETURN_EXCEEDS")
        perishable = s["items"][sku]["shelf"] is not None
        restock = True
        if perishable:
            if self._restock_perish is None:
                raise DepotError("RETURN_POLICY_UNDECIDED")
            restock = bool(self._restock_perish)
        if restock and self._units(wh=wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")
        prev = s["cash"]
        s["cash"] -= price * qty
        s["returned_sku"][sku] = s["returned_sku"].get(sku, 0) + qty
        if restock:
            self._add_lot(sku, wh, s["day"], qty)
        self._check_overdrawn(prev)

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._w(wh)
        return self._units(sku, wh)

    def report(self):
        rows = []
        for sku in sorted(self._s["items"]):
            for wh in sorted(self._wh):
                u = self._units(sku, wh)
                if u > 0:
                    rows.append((sku, wh, u, u * self._s["items"][sku]["unit_cost"]))
        return rows

    def turnover(self, start_day, end_day):
        s = self._s
        if not (0 <= start_day <= end_day <= s["day"]):
            raise DepotError("INVALID_RANGE")
        days = range(start_day, end_day + 1)
        shipped = sum(s["shipped"][d] for d in days)
        held = [s["held"][d] if d < s["day"] else self._units() for d in days]
        avg = Decimal(sum(held)) / Decimal(len(held))
        if avg == 0:
            return None
        return float(Decimal(shipped) / avg)

    def undo(self):
        if self._blocked:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        self._s = self._undo
        self._undo = None

    @property
    def cash(self):
        return self._s["cash"]

    @property
    def day(self):
        return self._s["day"]

    # ---------- persistence ----------
    def save(self):
        s = self._s
        d = {
            "version": 1,
            "warehouses": self._wh,
            "cash": s["cash"], "day": s["day"], "items": s["items"],
            "lots": [[k[0], k[1], l[0], l[1]] for k, v in s["lots"].items() for l in v],
            "log": [list(n) for n in s["log"]],
            "rel": s["rel"], "suspended": s["suspended"],
            "orders": {str(k): v for k, v in s["orders"].items()},
            "next_order": s["next_order"],
            "shipped_sku": s["shipped_sku"], "returned_sku": s["returned_sku"],
            "armed": [[k[0], k[1], v] for k, v in s["armed"].items()],
            "shipped": s["shipped"], "held": s["held"],
        }
        return json.dumps(d)

    @_tx()
    def _noop(self):  # pragma: no cover
        pass

    def load(self, text):
        try:
            d = json.loads(text)
            if not isinstance(d, dict) or d.get("version") != 1 \
                    or isinstance(d.get("version"), bool):
                raise ValueError
            if d["warehouses"] != self._wh:
                raise ValueError
            lots = {}
            for sku, wh, day, q in d["lots"]:
                if wh not in self._wh:
                    raise ValueError
                lots.setdefault((sku, wh), []).append([int(day), int(q)])
            new = {
                "cash": int(d["cash"]), "day": int(d["day"]),
                "items": dict(d["items"]), "lots": lots,
                "log": [tuple(n) for n in d["log"]],
                "rel": dict(d["rel"]), "suspended": list(d["suspended"]),
                "orders": {int(k): v for k, v in d["orders"].items()},
                "next_order": int(d["next_order"]),
                "shipped_sku": dict(d["shipped_sku"]),
                "returned_sku": dict(d["returned_sku"]),
                "armed": {(a, b): bool(c) for a, b, c in d["armed"]},
                "shipped": [int(x) for x in d["shipped"]],
                "held": [int(x) for x in d["held"]],
            }
            for it in new["items"].values():
                it["unit_cost"], it["reorder_level"], it["shelf"]
            if len(new["shipped"]) != new["day"] + 1 or len(new["held"]) != new["day"]:
                raise ValueError
        except Exception:
            raise DepotError("BAD_SAVE")
        self._s = new
        self._undo = None
        self._blocked = False


def simulate(days, seed):
    rng = random.Random(seed)
    out = []
    for _ in range(days):
        day = []
        for sku in sorted(_DATA["demand"]):
            r = _DATA["demand"][sku]
            q = rng.randint(r["min"], r["max"])
            if q > 0:
                day.append((sku, q))
        out.append(day)
    return out
